import pytest
from envcfg import load_config, ConfigError

def test_default_config():
    defaults = {'server': {'port': 8080}}
    config = load_config(defaults)
    assert config == {'server': {'port': 8080}}

def test_toml_config():
    defaults = {'server': {'port': 8080}}
    toml_content = b'[server]\nport = 9090\n'
    with open('config.toml', 'wb') as f:
        f.write(toml_content)
    config = load_config(defaults, toml_path='config.toml')
    assert config == {'server': {'port': 9090}}
    os.remove('config.toml')

def test_env_config():
    defaults = {'server': {'port': 8080}}
    env_mapping = {'APP__SERVER__PORT': '9090'}
    config = load_config(defaults, env_prefix='APP__', env_mapping=env_mapping)
    assert config == {'server': {'port': 9090}}

def test_missing_toml_config():
    defaults = {'server': {'port': 8080}}
    config = load_config(defaults, toml_path='nonexistent.toml')
    assert config == {'server': {'port': 8080}}

def test_coerce_int():
    defaults = {'server': {'port': 8080}}
    env_mapping = {'APP__SERVER__PORT': '9090'}
    config = load_config(defaults, env_prefix='APP__', env_mapping=env_mapping)
    assert config['server']['port'] == 9090

def test_coerce_float():
    defaults = {'server': {'timeout': 1.0}}
    env_mapping = {'APP__SERVER__TIMEOUT': '2.5'}
    config = load_config(defaults, env_prefix='APP__', env_mapping=env_mapping)
    assert config['server']['timeout'] == 2.5

def test_coerce_bool():
    defaults = {'server': {'enabled': False}}
    env_mapping = {'APP__SERVER__ENABLED': 'true'}
    config = load_config(defaults, env_prefix='APP__', env_mapping=env_mapping)
    assert config['server']['enabled'] == True

def test_coerce_string():
    defaults = {'server': {'name': 'default'}}
    env_mapping = {'APP__SERVER__NAME': 'custom'}
    config = load_config(defaults, env_prefix='APP__', env_mapping=env_mapping)
    assert config['server']['name'] == 'custom'

